export const INITIAL={org:'federated',data:'hybrid',model:'future',rights:'unknown',archive:'unknown',analysis:'new',host:'academy',repos:'hybrid',stack:'xml'};
export function workflowOutcome(roundtrip,markers){return {affected:!!(roundtrip&&markers),text:!roundtrip?'Dieser Kommentar bleibt im bisherigen Bearbeitungsweg. Der beschriebene Rückimport greift hier nicht.':!markers?'Der Kommentar passiert die neue Oberfläche, enthält aber keines der betroffenen Zeichen. Der fehlerhafte Rückweg fällt in diesem Fall nicht auf.':'Beide Bedingungen treffen zusammen: Der Rückweg verändert relevante Zeichen. Zahlenerkennung, Register und abhängige Ausgaben können dadurch auseinanderlaufen.'};}
export function evaluate(s){return {
organisation:s.org==='federated'?'Eigene fachliche Zuständigkeiten, gemeinsame Regeln und regelmäßige Integration. Dafür braucht es ein mandatiertes gemeinsames Redaktionsteam.':s.org==='central'?'Gemeinsame Entscheidungen und Prüfungen können leichter koordiniert werden. Die zentrale Redaktion benötigt ausreichend Kapazität und Vertretung, damit sie nicht zum Engpass wird.':'Hohe lokale Beweglichkeit. Gemeinsame IDs, Mindeststandards und verbindliche Übergaben bleiben nötig; späte Integration kann zusätzliche Arbeit verursachen.',
architecture:s.data==='hybrid'?'TEI und Skripte werden in Git gepflegt; das gemeinsame Register in der Registerdatenbank. Reproduzierbare Snapshots verbinden beide. Jede Datenart hat genau einen maßgeblichen Pflegeort.':s.data==='git'?'TEI, Regeln und Registerdateien werden in Git gepflegt. Datenbanken dienen als daraus abgeleitete Abfrage- und Ausgabeschicht.':'Die Datenbank ist der maßgebliche Pflegeort der Editionsdaten. Git hält Code, Schema und definierte Exporte. Die Datenbank braucht eigene Audit-, Sicherungs- und Versionsregeln.',
model:s.model==='migrate'?'Eine Migration kann ein gemeinsames Modell herstellen. Altbestände müssen fachlich geprüft, Migrationsskripte versioniert und bereits publizierte Stände erhalten werden. Der Aufwand braucht Finanzierung.':s.model==='parallel'?'Frühere Fassungen bleiben in ihrem Modell erhalten. Mehrere Prüf- und Ausgabewege müssen parallel gepflegt und eindeutig zugeordnet werden.':s.model==='core'?'Ein semantisch stabiler Kern kann verschiedene technische Repräsentationen verbinden. Dafür sind explizite Abbildungen, Tests und langfristige Modellierungsarbeit nötig; verlustfreie Umwandlung darf nicht vorausgesetzt werden.':'Neue Regeln gelten zunächst nur für künftige Bände. Geringerer unmittelbarer Umbau; Unterschiede zwischen Bänden müssen erklärt und bei übergreifender Nutzung berücksichtigt werden.',
host:s.host==='academy'?'Ein gemeinsamer Akademieträger kann Betrieb und Nachfolge über einzelne Arbeitsstellen hinweg organisieren. Finanzierung, Serviceumfang, Zugriffe und Exit müssen verbindlich zugesagt werden.':s.host==='uni'?'Eine federführende Universität kann vorhandenen Git-Betrieb und Beratung bieten. Partnerzugänge, Dienstbedingungen und Übergabe beim Ende der Anbindung sind ausdrücklich zu klären.':'Ein externer Dienst kann die technische Bereitstellung erleichtern. Verträge, Kostenentwicklung, Berechtigungen, Export und konkret einschlägige Datenschutzfragen bleiben institutionelle Aufgaben.',
repos:s.repos==='hybrid'?'Bereichsrepos halten fachlich zusammenhängende Arbeit zusammen; ein Standards-Repo verbindet Schema, IDs und Regeln. Versionsabhängigkeiten werden im Bandmanifest festgehalten.':s.repos==='mono'?'Ein Gesamtrepo erleichtert gemeinsame Änderungen und einheitliche Prüfungen. Unterschiedliche Leserechte lassen sich darin nicht einfach durch Branches abbilden; gemeinsame Integrationslast und Größe mitbedenken.':'Band-/Paketrepos geben lokalen Freigaben klare Grenzen. Gemeinsame Register und Modellversionen müssen repoübergreifend abgestimmt werden; ein Band ist nicht automatisch eine unabhängige Dateneinheit.',
stack:s.stack==='xml'?'Für den XML-Weg wird eXist-db mit TEI Publisher an einem Testkorpus erprobt; BaseX ist eine Alternative für XML-Abfragen und Anwendungen. Redaktionelle Bedürfnisse, Ausgabe und Betrieb entscheiden über die Wahl.':s.stack==='relational'?'PostgreSQL ist ein möglicher Pflegeort für strukturierte Register. TEI bleibt ein eigener Datengegenstand. Import, Exporte, IDs und die Web-/Satzanbindung benötigen definierte Schnittstellen.':'Eine Graphdatenbank kann vernetzte Informationen und Forschungsabfragen unterstützen. Zunächst als abgeleitete Analyseschicht prüfen; zusätzliche Technik ist kein Selbstzweck. Maßgebliche Datenpflege und Rückwege klar festlegen.',
publicationAllowed:s.rights==='approved',
review:s.org==='central'?'Eine zentrale Redaktion kann Rückmeldungen bündeln; sie braucht Kapazität für zeitnahe Antworten und eine geregelte Eskalation. Gutachten bleiben fachlich eigenständige Urteile.':s.org==='autonomous'?'Eigenständige Bandredaktionen benötigen gemeinsame Mindestkriterien und einen eindeutigen Weg für Gutachten, Antworten und Freigaben.':'Gemeinsame Reviewregeln verbinden die Bandredaktionen. Prüfstand, vertraulicher Rückkanal und Entscheidung über erneute Begutachtung werden festgelegt.',
publication:s.rights==='approved'?'Im Szenario ist dieses abgegrenzte Paket fachlich und rechtlich freigegeben. Ein kuratierter Export kann veröffentlicht werden; private Geschichte und vertrauliche Gutachten bleiben außen vor.':s.rights==='embargo'?'Für das gewählte Paket besteht noch ein Embargo. Ein Fristende löst eine Prüfung der konkreten Gegenstände und Bedingungen aus; es gibt nicht automatisch jede Datei frei.':'Die Freigabe ist ungeklärt. Öffentliche Publikation ist hier noch kein bestätigter nächster Schritt. Vertrag, Drittmaterial, Zuständigkeit und fachliche Freigabe klären.',
archive:s.archive==='complete'?'Im Szenario sind Daten, Schema, Register-Snapshot und Ausgabeweg erhalten und der Neuaufbau wurde geprüft. Regelmäßig wiederholen; künftige Verfügbarkeit ist damit nicht garantiert.':s.archive==='missing'?'Der Register-Snapshot fehlt. Der Text ist erhalten, aber dieser Bandstand ist nicht vollständig reproduzierbar. Lücke dokumentieren und Wiederbeschaffung oder verantwortete Neufassung prüfen.':'Die Wiederherstellung ist ungeprüft. Ein Manifest nennt Bestandteile, beweist aber weder deren Erhalt noch einen funktionierenden Neuaufbau.',
analysis:s.analysis==='agreed'?'Zweck, Umfang, Zugriff und Einspruchsweg sind vorab geregelt. Das unterstützt faire Prozesssteuerung, beseitigt Personenbezug aber nicht. Zulässigkeit und Einhaltung bleiben zu prüfen.':s.analysis==='expanded'?'Ein neuer Zweck oder eine wesentlich tiefere Auswertung benötigt eine erneute transparente Prüfung und Regelung vor dem Einsatz. Eine frühere Vereinbarung ist keine unbegrenzte Erlaubnis.':'Nach Jahren wird eine neue Analyse eingeführt. Präzise Verbesserungen sind möglich; Mitarbeitende und frühere Beteiligte werden zugleich nachträglich sichtbar. Vor dem Einsatz Umfang, Zulässigkeit, Beteiligung und Einspruch klären.'};}
